","service":"class CoCoMEOrderProducts_AutoGenerated {
  /*SystemVariable Start*/
  CurrentCashDesk: CashDesk;
  CurrentStore: Store;
  /*SystemVariable End*/

  /*Definition: The orderItem operation handles its intended business action in this system.
   *Precondition: Required inputs are present, referenced data is valid, and the action is allowed by business rules.
   *Postcondition: The system applies the requested outcome, keeps data consistent, and returns the defined result.*/
  orderItem(barcode: number, quantity: number): boolean {
    /*Definition Start*/
    let item: Item = l({
      logic: () =>
        getRepository(Item).find(
          (i: Item) =>
            l({
              logic: () => i.Barcode === barcode,
              description: "i.Barcode=barcode",
            }).build().pass,
        ),
      description: "Item.allInstance()->any(i:Item|i.Barcode=barcode)",
    }).build().pass;
    let orderProduct: OrderProduct = l({
      logic: () =>
        getRepository(OrderProduct).find(
          (op: OrderProduct) =>
            l({
              logic: () => op.OrderStatus === OrderStatus.NEW,
              description: "op.OrderStatus=OrderStatus::NEW",
            }).build().pass,
        ),
      description:
        "OrderProduct.allInstance()->any(op:OrderProduct|op.OrderStatus=OrderStatus::NEW)",
    }).build().pass;
    let orderEntry: OrderEntry = l({
      logic: () =>
        orderProduct.ContainedEntries.find(
          (oe: OrderEntry) =>
            l({
              logic: () => oe.Item === item,
              description: "oe.Item=item",
            }).build().pass,
        ),
      description:
        "orderProduct.ContainedEntries->any(oe:OrderEntry|oe.Item=item)",
    }).build().pass;
    /*Definition End*/

    /*Precondition Start*/
    const { errorMessage: preconditionErrorMessage, pass: isPreconditionPass } =
      l({
        logic: () => StandardOPs.oclIsTypeOf(barcode, Integer),
        description: "barcode.oclIsTypeOf(Integer)",
      })
        .and({
          logic: () => StandardOPs.oclIsTypeOf(quantity, Integer),
          description: "quantity.oclIsTypeOf(Integer)",
        })
        .and({
          logic: () => StandardOPs.oclIsUndefined(item) === false,
          description: "item.oclIsUndefined()=false",
        })
        .and({
          logic: () => StandardOPs.oclIsUndefined(orderProduct) === false,
          description: "orderProduct.oclIsUndefined()=false",
        })
        .and({
          logic: () => orderProduct.OrderStatus === OrderStatus.NEW,
          description: "orderProduct.OrderStatus=OrderStatus::NEW",
        })
        .and({
          logic: () => item.StockNumber >= quantity,
          description: "item.StockNumber>=quantity",
        })
        .and({
          logic: () => getRepository(OrderProduct).includes(orderProduct),
          description: "OrderProduct.allInstance()->includes(orderProduct)",
        })
        .and({
          logic: () => getRepository(Item).includes(item),
          description: "Item.allInstance()->includes(item)",
        })
        .build();
    if (!isPreconditionPass) {
      throw new PreconditionError(preconditionErrorMessage);
    }
    /*Precondition End*/

    /*Postcondition Start*/
    return l({
      execute: () => (orderEntry.Quantity = quantity),
      description: "orderEntry.Quantity=quantity",
    })
      .and({
        execute: () => (orderEntry.SubAmount = item.OrderPrice * quantity),
        description: "orderEntry.SubAmount=item.OrderPrice*quantity",
      })
      .and({
        execute: () => (item.StockNumber = item.StockNumber - quantity),
        description: "item.StockNumber=item.StockNumber-quantity",
      })
      .and({
        execute: () =>
          (orderProduct.Amount = orderProduct.Amount + orderEntry.SubAmount),
        description:
          "orderProduct.Amount=orderProduct.Amount+orderEntry.SubAmount",
      })
      .and({
        execute: () => orderProduct.ContainedEntries.push(orderEntry),
        description: "orderProduct.ContainedEntries->includes(orderEntry)",
      })
      .and({
        execute: () => true,
        description: "result=true",
      })
      .build().value;
    /*Postcondition End*/
  }
}
